#!/usr/bin/env python3
"""Minimal, dependency-free API CLI generated by connect-tool.

Fill TOOL, ENV_KEY, BASE_URL, KEY_URL, SETTINGS, auth_headers and COMMANDS
from the tool's official API documentation.
"""

import getpass
import json
import os
import re
import sys
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path

TOOL = "tool"
ENV_KEY = "TOOL_API_KEY"
BASE_URL = "https://api.example.com/v1"
KEY_URL = "https://example.com/settings/api"
SETTINGS = {}


def auth_headers(key: str) -> dict:
    return {"Authorization": f"Bearer {key}"}


COMMANDS = {
    "check": ("GET", "/me", "Check that the configured credentials work"),
}

CONFIG = Path.home() / ".config" / f"{TOOL}-cli" / "config.json"
TIMEOUT = 30


def fail(message: str) -> None:
    print(f"Error: {message}", file=sys.stderr)
    raise SystemExit(1)


def load_config() -> dict:
    if not CONFIG.exists():
        return {}
    try:
        return json.loads(CONFIG.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        fail(f"cannot read {CONFIG}: {exc}")


def save_config(config: dict) -> None:
    CONFIG.parent.mkdir(parents=True, exist_ok=True)
    fd = os.open(CONFIG, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        json.dump(config, handle, indent=2)
    CONFIG.chmod(0o600)


def substitute(template: str, args: list, config: dict) -> str:
    def replace(match):
        name = match.group(1)
        if name.isdigit():
            index = int(name)
            if index >= len(args):
                fail(f"missing positional argument {index + 1}")
            value = args[index]
        else:
            value = config.get(name)
            if value is None:
                fail(f"missing setting: {name}")
        return urllib.parse.quote(str(value), safe="")

    return re.sub(r"\{(\w+)\}", replace, template)


def request(method: str, path: str, args: list, options: dict) -> None:
    config = load_config()
    key = os.environ.get(ENV_KEY) or config.get("api_key")
    if not key:
        fail(f"no API key. Run: {sys.argv[0]} login")

    if method == "DELETE" and not options.get("yes"):
        fail("destructive operation requires --yes")

    url = substitute(BASE_URL, [], config).rstrip("/") + substitute(path, args, config)
    if options.get("query"):
        url += "?" + urllib.parse.urlencode(options["query"])

    data = options.get("data")
    if data == "-":
        data = sys.stdin.read()
    if data:
        try:
            data = json.dumps(json.loads(data)).encode("utf-8")
        except json.JSONDecodeError:
            fail("--data must contain valid JSON")

    headers = {
        "Accept": "application/json",
        "User-Agent": f"{TOOL}-cli/2.0",
        **auth_headers(key),
    }
    if data:
        headers["Content-Type"] = "application/json"

    req = urllib.request.Request(url, data=data or None, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=TIMEOUT) as response:
            body = response.read().decode("utf-8", errors="replace")
            status = response.status
    except urllib.error.HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        status = exc.code
    except urllib.error.URLError as exc:
        fail(f"network error: {exc.reason}")

    try:
        body = json.dumps(json.loads(body), indent=2, ensure_ascii=False)
    except json.JSONDecodeError:
        pass

    stream = sys.stdout if 200 <= status < 300 else sys.stderr
    print(body, file=stream)
    raise SystemExit(0 if 200 <= status < 300 else 1)


def login(options: dict) -> None:
    config = load_config()
    if sys.stdin.isatty():
        print(f"Create an API key with the narrowest permissions: {KEY_URL}")
        config["api_key"] = getpass.getpass("API key (hidden): ").strip()
    else:
        config["api_key"] = sys.stdin.read().strip()

    for name, question in SETTINGS.items():
        config[name] = options.get(name) or input(f"{question}: ").strip()

    missing = [name for name in ["api_key", *SETTINGS] if not config.get(name)]
    if missing:
        fail(f"missing value(s): {', '.join(missing)}")

    save_config(config)
    print(f"Credentials saved to {CONFIG}")
    request(*COMMANDS["check"][:2], [], {})


def usage() -> None:
    rows = [("login", "Store credentials securely"), ("logout", "Remove stored credentials")]
    rows.extend((name, command[2]) for name, command in COMMANDS.items())
    rows.append(("api", "api <METHOD> <path> [args...]"))
    print(f"Usage: {sys.argv[0]} <command> [args] [--data JSON|-] [--query key=value] [--yes]\n")
    print("\n".join(f"  {name:<20} {help_text}" for name, help_text in rows))


def main() -> None:
    args, options, argv = [], {"query": []}, sys.argv[1:]
    while argv:
        item = argv.pop(0)
        if item == "--yes":
            options["yes"] = True
        elif item.startswith("--"):
            name, _, value = item[2:].partition("=")
            if not value:
                value = argv.pop(0) if argv else fail(f"--{name} requires a value")
            if name == "query":
                options["query"].append(tuple(value.split("=", 1) + [""])[:2])
            else:
                options[name] = value
        else:
            args.append(item)

    command, rest = (args[0], args[1:]) if args else ("help", [])
    if command == "login":
        login(options)
    elif command == "logout":
        CONFIG.unlink(missing_ok=True)
        print("Stored credentials removed.")
    elif command == "api" and len(rest) >= 2:
        request(rest[0].upper(), "/" + rest[1].lstrip("/"), rest[2:], options)
    elif command in COMMANDS:
        request(*COMMANDS[command][:2], rest, options)
    else:
        usage()


if __name__ == "__main__":
    main()
